/* Business-first experience and geographic overview. All business records are demo data. */
let geoMap=null,baseLayer=null,siteMarkers=[],mapSelection=-1,mapTheme='street',networkOpen=false,drawerOpen=false;
const coordinates=[[29.953,30.878],[30.373,30.532],[30.91,29.69],[29.644,32.329]];
const business={
'Sustainability':{headline:'Resource efficiency that supports profitable growth',insight:'Water recovery is ahead of target. Energy intensity is the largest remaining efficiency opportunity.',metrics:[['Energy cost per unit','EGP 0.84','Target EGP 0.90'],['Water reused','68%','Target 65%'],['Carbon footprint','124 tCO₂e','8% below baseline'],['Waste recovery','92%','Target 90%']],items:[['Energy performance','Consumption, spend and intensity','EGP 360k monthly cost'],['Water stewardship','Reuse and consumption targets','2,640 m³ consumed'],['Environmental impact','Emissions and waste recovery','124 tCO₂e']]},
'Facility':{headline:'Reliable facilities. Protected production.',insight:'Utilities are supporting planned production. One air-handling inspection is due; no production impact is expected.',metrics:[['Facility availability','99.4%','Target 99.0%'],['Utility spend','EGP 148k','Within daily budget'],['Production at risk','0 h','No critical disruption'],['Open facility actions','3','1 inspection due']],items:[['Building operations','Comfort, controlled spaces and readiness','98% areas within target'],['Energy & utilities','Power, water, steam and compressed air','EGP 148k today'],['Facility readiness','Availability and service continuity','99.4% available']]},
'Maintenance':{headline:'Protect uptime. Prioritize business impact.',insight:'Pump P-104 has an early advisory. Planning its inspection during changeover avoids a potential production interruption.',metrics:[['Asset availability','97.8%','Target 97%'],['Planned work completed','92%','11 of 12 scheduled tasks'],['Unplanned downtime','1.6 h','0.4 h below target'],['Production value at risk','EGP 42k','Advisory estimate']],items:[['Pump P-104','Process area · Vibration advisory','Impact estimate: EGP 42k'],['Motor M-201','Packaging line 1 · Healthy','Availability: 99.2%'],['Compressor C-01','Utilities · Service scheduled','Next service: 14 Nov']]},
'Workforce Mgmt':{headline:'The right people. Qualified and ready.',insight:'Shift coverage is complete. Four training renewals are due within the next 30 days.',metrics:[['Shift coverage','100%','148 people on shift'],['Training compliance','96%','Target 100%'],['Qualified technicians','24','Across maintenance roles'],['Assigned work completed','89%','8 assignments remaining']],items:[['Shift readiness','Availability, coverage and assignments','148 people available'],['Skills & qualifications','Role eligibility and certifications','96% training compliant'],['Maintenance assignments','Match jobs to qualified technicians','8 open assignments']]},
'Supply Chain':{headline:'Reliable supply. On-time customer delivery.',insight:'Delivery performance is above target. One API order needs review to maintain next week’s inventory coverage.',metrics:[['On-time delivery','94.6%','Target 93%'],['Inventory coverage','24 days','Target 21–28 days'],['Supplier quality','98.1%','Target 98%'],['Orders at risk','2','Review required']],items:[['Material availability','Inventory, coverage and shortages','24 days of coverage'],['Supplier performance','Quality, lead time and reliability','98.1% quality acceptance'],['Customer delivery','Orders, dispatch and cold chain','94.6% delivered on time']]}}
const originalRender=render,originalProduction=production,originalQuality=quality;
factories.forEach((f,i)=>{f.revenue=[3.8,4.2,2.9,3.4][i];f.delivery=[96.1,97.2,92.4,95.6][i];f.output=[128640,116200,86300,97500][i]});
function networkMetrics(){return [['Production plan attainment','94.8%','Target 95%'],['First-pass quality','98.2%','Target 98%'],['On-time delivery','95.4%','Target 93%'],['Operational risk','1 site','Requires review']]}
function businessCards(metrics){return metrics.map(m=>card(m[0],m[1],m[2])).join('')}
function showNetwork(){networkOpen=!networkOpen;document.querySelector('.network-panel')?.remove();if(!networkOpen)return;const div=document.createElement('section');div.className='network-panel';div.innerHTML=`<div class="row"><div><h2>Enterprise performance</h2><p class="map-help">Today · 4 factories · Simulated business data</p></div><button onclick="showNetwork()" aria-label="Close performance panel">×</button></div><div class="kpis">${businessCards(networkMetrics())}</div><div class="insight">Alexandria packaging is below its production target. Review line performance to protect delivery commitments.</div>`;document.body.appendChild(div)}
function toggleNavigation(){drawerOpen=!drawerOpen;$('#nav').classList.toggle('open',drawerOpen);$('.navigation-handle').classList.toggle('open',drawerOpen);$('.navigation-handle').setAttribute('aria-expanded',drawerOpen)}
function selectMapFactory(i,fly=true){mapSelection=i;siteMarkers.forEach((m,n)=>m.getElement()?.querySelector('.site-orb')?.classList.toggle('selected',i===n));document.querySelector('.map-detail')?.remove();const f=factories[i];const pane=document.createElement('section');pane.className='map-detail';pane.innerHTML=`<button class="close" aria-label="Close factory summary" onclick="closeMapSelection()">×</button><div class="eyebrow">FACTORY BUSINESS SNAPSHOT</div><h2>${f.name}</h2><div class="location">${f.city} · Egypt</div><div style="margin-top:14px"><span class="pill" style="${i===2?'color:#ffc776;border-color:#ffc77644':''}">${i===2?'Attention required':'Operations on track'}</span></div><div class="quickmetrics"><div><strong>${f.oee}%</strong><small>Equipment effectiveness</small></div><div><strong>${f.delivery}%</strong><small>On-time delivery</small></div><div><strong>${(f.output/1000).toFixed(1)}k</strong><small>Units produced today</small></div><div><strong>98.${i+1}%</strong><small>First-pass quality</small></div></div><button class="primary" onclick="enterFactory(${i})">Explore factory operations &nbsp; →</button><div class="insight">${i===2?'Packaging output needs review to protect the delivery plan.':'Production and quality are tracking within the operating plan.'}</div>`;document.body.appendChild(pane);if(fly&&geoMap)geoMap.flyTo(coordinates[i],Math.max(geoMap.getZoom(),8),{duration:.7});$('#factory').value=i}
function closeMapSelection(){mapSelection=-1;document.querySelector('.map-detail')?.remove();siteMarkers.forEach(m=>m.getElement()?.querySelector('.site-orb')?.classList.remove('selected'));$('#factory').value=-1}
function enterFactory(i){state.factory=i;state.tab='Factory Overview';state.area='All areas';render()}
function changeMap(theme){mapTheme=theme;if(!geoMap)return;if(baseLayer)geoMap.removeLayer(baseLayer);let url=theme==='dark'?'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png':'https://tile.openstreetmap.org/{z}/{x}/{y}.png';baseLayer=L.tileLayer(url,{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'+(theme==='dark'?' &copy; CARTO':'')});let failures=0;baseLayer.on('tileerror',()=>{if(++failures===8){$('#tileNotice').textContent='Map tiles unavailable · check your internet connection';$('#tileNotice').classList.add('show')}});baseLayer.on('load',()=>{if(failures<8)$('#tileNotice')?.classList.remove('show')});baseLayer.addTo(geoMap);document.querySelectorAll('[data-maptheme]').forEach(b=>b.classList.toggle('active',b.dataset.maptheme===theme))}
function fitEgypt(){closeMapSelection();if(geoMap)geoMap.flyToBounds([[22,24.7],[31.8,35.9]],{padding:[20,20],duration:.8})}
function buildMap(){document.body.classList.add('map-mode');$('#main').innerHTML=`<div class="full-map" id="geoMap"><div class="offline-grid"></div></div><div id="tileNotice" class="map-empty"></div><div class="map-switcher"><button data-maptheme="street" onclick="changeMap('street')">Street map</button><button data-maptheme="dark" onclick="changeMap('dark')">Night map</button><button onclick="fitEgypt()">Fit Egypt</button></div><div class="map-tag">SIMULATED FACTORY DATA</div><div class="map-bottom"><button onclick="showNetwork()">◈ &nbsp; Enterprise performance</button><button onclick="showFactoryDirectory()">⌖ &nbsp; Factory directory</button><span class="light">Select a factory marker to explore</span></div>`;if(!window.L){$('#tileNotice').textContent='Map engine could not load. Use the factory selector or directory to continue.';$('#tileNotice').classList.add('show');return}geoMap=L.map('geoMap',{zoomControl:false,minZoom:5,maxZoom:16,preferCanvas:true,maxBounds:[[18,18],[38,43]],maxBoundsViscosity:.8}).setView([27.1,30.4],6);L.control.zoom({position:'bottomright'}).addTo(geoMap);L.control.scale({position:'bottomleft',imperial:false}).addTo(geoMap);changeMap(mapTheme);siteMarkers=factories.map((f,i)=>L.marker(coordinates[i],{icon:L.divIcon({className:'site-marker',html:`<div class="site-orb ${i===2?'attention':''}"></div>`,iconSize:[25,25],iconAnchor:[12,12]}),title:f.name,keyboard:true}).addTo(geoMap).bindTooltip(`<strong>${f.name}</strong><br>${f.city} · ${f.oee}% OEE`,{className:'factory-tooltip',direction:'top',offset:[0,-15]}).on('click',()=>selectMapFactory(i)));geoMap.fitBounds([[22,24.7],[31.8,35.9]],{padding:[15,15]});setTimeout(()=>geoMap?.invalidateSize(),80)}
function showFactoryDirectory(){openModal('Factory directory',factories.map((f,i)=>`<button class="action" style="display:block;width:100%;text-align:left;margin:10px 0" onclick="$('#modal').close();selectMapFactory(${i})"><strong>${f.name}</strong><br><small>${f.city} · OEE ${f.oee}% · ${f.status}</small></button>`).join(''))}
function businessSection(){const d=business[state.tab];return `<div class="business-strip"><strong>Business outlook</strong><span>${d.insight}</span></div><div class="entity-grid">${d.items.map((r,i)=>`<button class="entity" onclick="businessDetail(${i})"><div class="entity-icon">${['◈','◎','⌁'][i]}</div><strong>${r[0]} &nbsp; ↗</strong><small>${r[1]}</small><div class="insight">${r[2]}</div></button>`).join('')}</div><div class="lower">${bars(state.tab==='Maintenance'?'Downtime impact':state.tab==='Supply Chain'?'Delivery performance':state.tab==='Workforce Mgmt'?'Work completion':'Performance against plan')}${bars(state.tab==='Sustainability'?'Resource efficiency':'Weekly business trend')}${businessAttention()}</div>`}
function businessAttention(){return `<div class="panel"><div class="panelhead"><h2>Decisions & actions</h2><span class="pill">Today</span></div>${['Review packaging output against delivery plan','Schedule pump inspection during changeover','Review training renewals for next month'].map((x,i)=>`<div class="alarm"><span class="dot" style="background:${i?'#67c9db':'#efb855'}"></span>${x}<small>${['Production leadership','Maintenance planning','Workforce planning'][i]}</small><button style="margin-top:9px;font-size:10px" onclick="openAction(${i})">Review action ↗</button></div>`).join('')}</div>`}
function openAction(i){openModal(['Protect the delivery plan','Plan preventive maintenance','Maintain workforce readiness'][i],['Packaging line 2 is below its planned output. Business impact: potential delay to two customer orders.<br><br>Suggested action: review changeover duration and prioritize the affected orders.','Pump P-104 has an early health advisory. Estimated production value at risk: EGP 42,000.<br><br>Suggested action: assign a qualified technician and inspect during the next planned changeover.','Four training renewals are due within 30 days.<br><br>Suggested action: arrange refresher sessions before expiry to maintain full role coverage.'][i]+'<br><br><small>Illustrative decision support; no live action is executed.</small>')}
function businessDetail(i){const d=business[state.tab],r=d.items[i];openModal(r[0],`${r[1]}<br><br><strong>${r[2]}</strong><br><br>${d.insight}<br><br><small>Scope: ${state.factory<0?'All factories':factories[state.factory].name} · ${$('#period').value} · Simulated data</small>${state.tab==='Maintenance'?'<br><button class="action" onclick="openAction(1)">Review maintenance action →</button>':''}`)}
production=function(){return `<div class="business-strip"><strong>Production outlook</strong><span>${state.tab==='Packaging'?'Line 2 changeover is the main constraint. Review its delivery impact and recovery plan.':'Production is at 94.8% of plan. Select a line to review throughput, quality and progress.'}</span></div>`+originalProduction()};
quality=function(){return `<div class="business-strip"><strong>Quality outlook</strong><span>98.2% first-pass yield is above target. Track customer experience, delivery and quality cost together.</span></div>`+originalQuality()};
function pageMetrics(){const factor=state.factory<0?1:[.3,.27,.2,.23][state.factory],mult=$('#period').value==='Today'?1:$('#period').value==='This week'?7:30;if(business[state.tab])return business[state.tab].metrics;if(state.tab==='Quality')return [['First-pass yield','98.2%','Target 98%'],['Customer satisfaction','92%','Target 90%'],['Cost of poor quality','EGP '+Math.round(32*factor*mult)+'k','Below 2% of output value'],['Batches awaiting release',state.factory<0?'6':'2','Quality review pending']];if(state.tab==='Packaging')return [['Packaging plan attainment','92.4%','Target 95%'],['Units packaged',(Math.round(312*factor*mult)).toLocaleString()+'k','Selected period'],['Packaging reject rate','1.2%','Target below 1.5%'],['Delivery orders at risk','2','Recovery plan required']];return [['Production plan attainment',state.factory===2?'89.2%':'94.8%','Target 95%'],['Production output',Math.round(428640*factor*mult).toLocaleString(),'Units · selected period'],['First-pass quality','98.2%','Target 98%'],['On-time delivery',state.factory<0?'95.4%':factories[state.factory].delivery+'%','Target 93%']]}
render=function(){if(geoMap){geoMap.remove();geoMap=null;siteMarkers=[]}document.querySelectorAll('.map-detail,.network-panel').forEach(x=>x.remove());networkOpen=false;mapSelection=-1;document.body.classList.remove('map-mode');originalRender();if(!$('.navigation-handle')){const handle=document.createElement('button');handle.className='navigation-handle';handle.innerHTML='☰ &nbsp; NAVIGATION &nbsp; ›';handle.setAttribute('aria-label','Toggle navigation');handle.setAttribute('aria-expanded','false');handle.onclick=toggleNavigation;document.body.appendChild(handle)}$('#nav').classList.toggle('open',drawerOpen);$('.navigation-handle').classList.toggle('open',drawerOpen);if(state.tab==='Overview'){buildMap();return}$('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');$('.kpis').innerHTML=businessCards(pageMetrics());if(business[state.tab]){const title=$('.title');title.querySelector('p').textContent=business[state.tab].headline;let next=$('.kpis').nextElementSibling;while(next){let after=next.nextElementSibling;next.remove();next=after}$('.kpis').insertAdjacentHTML('afterend',businessSection())}if(state.tab==='Factory Overview'){const subtitle=$('.title p');subtitle.textContent='Business performance, operational readiness and the decisions that matter.';$('.kpis').insertAdjacentHTML('afterend','<div class="business-strip"><strong>Factory outlook</strong><span>Production, quality, delivery and operational risk in one view. Select an area below to explore.</span></div>')}$('.crumb').innerHTML=`<button onclick="$('#back').onclick()">Enterprise map</button> / <button onclick="go('Factory Overview')">${state.factory<0?'All factories':factories[state.factory].name}</button> / ${state.tab}`;document.querySelectorAll('.kpis .card').forEach((c,i)=>{c.tabIndex=0;c.setAttribute('role','button');const fn=()=>{let m=pageMetrics()[i];openModal(m[0],`<strong style="font-size:32px;color:var(--teal)">${m[1]}</strong><br>${m[2]}<br><br>Scope: ${state.factory<0?'All factories':factories[state.factory].name}<br>Period: ${$('#period').value}<br><br>Demonstration metric. Factory data integrations will supply its detailed trend and calculation.`)};c.onclick=fn;c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}}});document.querySelectorAll('.chart rect').forEach((r,i)=>{const v=r.getAttribute('height');r.innerHTML=`<title>Demo value: ${v} · Select to inspect</title>`;r.onclick=()=>openModal('Performance detail',`Selected period value: <strong>${v}</strong><br><br>This chart illustrates the business trend. Values are simulated and will be mapped to the selected KPI definition.`)});document.querySelectorAll('.linecard').forEach(c=>{c.tabIndex=0;c.setAttribute('role','button');c.onkeydown=e=>{if(e.key==='Enter')c.click()}})};
$('#factory').onchange=e=>{if(state.tab==='Overview'){const i=+e.target.value;if(i<0){closeMapSelection();fitEgypt()}else selectMapFactory(i)}else{state.factory=+e.target.value;state.tab=state.factory<0?'Overview':'Factory Overview';state.area='All areas';state.line=0;render()}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.tab==='Overview'){closeMapSelection();if(drawerOpen)toggleNavigation();if(networkOpen)showNetwork()}});
render();
